use std::collections::HashMap;

use super::point::{Path64, Paths64, Point64};

/// Winding rule used when deciding whether a region belongs to a polygon set.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum FillRule {
    NonZero,
}

/// Computes the union of a set of closed rectilinear contours.
///
/// The input x- and y-coordinates form an exact arrangement for rectilinear
/// contours. After classifying each elementary cell with the requested fill
/// rule, exposed cell edges are chained into the outer contours and holes of
/// the union. All classification arithmetic is integer-based.
pub fn union(subjects: &Paths64, fill_rule: FillRule) -> Paths64 {
    let mut xs = Vec::new();
    let mut ys = Vec::new();

    for path in subjects {
        for point in path {
            xs.push(point.x);
            ys.push(point.y);
        }
    }
    xs.sort_unstable();
    xs.dedup();
    ys.sort_unstable();
    ys.dedup();

    if xs.len() < 2 || ys.len() < 2 {
        return Vec::new();
    }

    let columns = xs.len() - 1;
    let rows = ys.len() - 1;
    let mut occupied = vec![false; columns * rows];

    for row in 0..rows {
        for column in 0..columns {
            let centre_x2 = i128::from(xs[column]) + i128::from(xs[column + 1]);
            let centre_y2 = i128::from(ys[row]) + i128::from(ys[row + 1]);
            occupied[row * columns + column] =
                is_in_subjects(subjects, centre_x2, centre_y2, fill_rule);
        }
    }

    let mut edges = Vec::new();
    for row in 0..rows {
        for column in 0..columns {
            if !occupied[row * columns + column] {
                continue;
            }

            let lower_left = Point64::new(xs[column], ys[row]);
            let lower_right = Point64::new(xs[column + 1], ys[row]);
            let upper_right = Point64::new(xs[column + 1], ys[row + 1]);
            let upper_left = Point64::new(xs[column], ys[row + 1]);

            if row == 0 || !occupied[(row - 1) * columns + column] {
                edges.push((lower_left, lower_right));
            }
            if column + 1 == columns || !occupied[row * columns + column + 1] {
                edges.push((lower_right, upper_right));
            }
            if row + 1 == rows || !occupied[(row + 1) * columns + column] {
                edges.push((upper_right, upper_left));
            }
            if column == 0 || !occupied[row * columns + column - 1] {
                edges.push((upper_left, lower_left));
            }
        }
    }

    trace_contours(edges)
}

fn trace_contours(edges: Vec<(Point64, Point64)>) -> Paths64 {
    let mut outgoing: HashMap<Point64, Vec<usize>> = HashMap::new();
    for (index, (start, _)) in edges.iter().enumerate() {
        outgoing.entry(*start).or_default().push(index);
    }

    let mut used = vec![false; edges.len()];
    let mut contours = Vec::new();

    for first_edge in 0..edges.len() {
        if used[first_edge] {
            continue;
        }

        used[first_edge] = true;
        let (start, mut current) = edges[first_edge];
        let mut contour = vec![start, current];

        while current != start {
            let Some(edge_index) = outgoing
                .get(&current)
                .and_then(|candidates| candidates.iter().find(|index| !used[**index]))
            else {
                break;
            };

            used[*edge_index] = true;
            current = edges[*edge_index].1;
            contour.push(current);
        }

        if current == start {
            contour.pop();
            contours.push(simplify_contour(contour));
        }
    }

    contours
}

fn simplify_contour(contour: Path64) -> Path64 {
    let mut simplified = Vec::with_capacity(contour.len());
    for point in contour {
        simplified.push(point);
        while simplified.len() >= 3 {
            let length = simplified.len();
            let previous = simplified[length - 3];
            let current = simplified[length - 2];
            let next = simplified[length - 1];
            if orientation(previous, current, next) != 0 {
                break;
            }
            simplified.remove(length - 2);
        }
    }
    simplified
}

